public static String generateStatement(Invoice invoice, Map<String, Play> plays) {
    double totalAmount = 0;
    int totalVolumeCredits = 0;
    StringBuilder result = new StringBuilder("Statement for " + invoice.getCustomer() + "\n");

    for (Performance perf : invoice.getPerformances()) {
        Play play = plays.get(perf.getPlayID());
        double thisAmount = calculateAmount(play, perf);
        int playCredits = calculateCredits(play, perf);
        totalVolumeCredits += playCredits;

        result.append(formatPerformance(play, perf, thisAmount));
        totalAmount += thisAmount;
    }
    result.append(formatFooter(totalAmount, totalVolumeCredits));
    return result.toString();
}

private static double calculateAmount(Play play, Performance perf) {
    double thisAmount = 0;
    switch (play.getType()) {
        case "tragedy":
            thisAmount = 40000;
            if (perf.getAudience() > 30) {
                thisAmount += 1000 * (perf.getAudience() - 30);
            }
            break;

        case "comedy":
            thisAmount = 30000;
            if (perf.getAudience() > 20) {
                thisAmount += 10000 + 500 * (perf.getAudience() - 20);
            }
            thisAmount += 300 * perf.getAudience();
            break;

        default:
            throw new IllegalArgumentException("Unknown type: " + play.getType());
    }
    return thisAmount;
}

private static int calculateCredits(Play play, Performance perf) {
    int volumeCredits = Math.max(perf.getAudience() - 30, 0);
    if ("comedy".equals(play.getType())) {
        volumeCredits += Math.floor(perf.getAudience() / 5);
    }
    return volumeCredits;
}

private static String formatPerformance(Play play, Performance perf, double amount) {
    return String.format(" %s: %s (%d seats)\n",
            play.getName(), NumberFormat.getCurrencyInstance(Locale.US).format(amount / 100),
            perf.getAudience());
}

private static String formatFooter(double totalAmount, int volumeCredits) {
    StringBuilder result = new StringBuilder();
    result.append(String.format("Amount owed is %s\n",
            NumberFormat.getCurrencyInstance(Locale.US).format(totalAmount / 100)));
    result.append(String.format("You earned %d credits\n", volumeCredits));
    return result.toString();
}
